\title{Height Is the Only Cost:\\
A Two-Sided Theory of Combination-Tree Depth\\ for Valuation-Depth Carriers}
\author{Aristotle (Harmonic)}
\date{2026-06-16}

\begin{document}
\maketitle

\begin{abstract}
We develop a complete, two-sided quantitative theory of the \emph{depth cost} incurred when a
value is built by repeated binary combination, governed by a single structural axiom---the
\textbf{unit-cost ultrametric law} $\depth(x \oplus y) \le \max(\depth x, \depth y) + 1$. We
call a set equipped with such a combining operation and depth measure a \emph{depth carrier}.
The foundational result is that for any combination tree $t$ over a depth carrier,
$\depth(\eval t) \le \maxLeafDepth(t) + \height(t)$: the only overhead of repeated combination
is the height of the tree. Our central contribution is the \textbf{height--leaf duality},
valid for \emph{every} binary tree: $\numLeaves \le 2^{\height}$ and $\height + 1 \le
\numLeaves$, which after taking base-2 logarithms yields the universal sandwich
$\clog{\numLeaves} \le \height \le \numLeaves - 1$. We prove this sandwich is \emph{tight at
both ends}: the balanced tree attains the floor $\clog{\numLeaves}$ and the caterpillar
attains the ceiling $\numLeaves - 1$, establishing balanced reassociation as provably optimal
and naive accumulation as provably worst, with an exponential gap between them. We further
establish: (i) a median-split construction realizing the optimal height for \emph{every} leaf
count; (ii) a scale-covariant generalization to an arbitrary cost constant $c$, giving
$\depth(\eval t) \le \maxLeafDepth(t) + c\cdot\height(t)$ with $c=1$ the least working
constant; (iii) a two-sided witness sandwich $\maxLeafDepth \le \eval \le \maxLeafDepth +
\height$; and (iv) a universal linear-overhead bound. We connect the framework to $p$-adic
Hensel lifting, functional composition, and tropical/ultrametric geometry. All results have
been formally verified.
\end{abstract}

\section{Introduction}

Many quantitative invariants behave \emph{sub-maximally} under a binary combining operation:
if $\depth$ measures complexity, combining two values rarely produces something deeper than
the deeper of the two by more than a bounded amount. The cleanest regime is the
\emph{unit-cost} one: a single combination deepens by at most one. This pattern recurs across
number theory ($p$-adic valuation levels), algebraic geometry (tropical/max-plus structures),
and the analysis of iterative algorithms (Newton/Hensel precision doubling).

We isolate the pattern as one axiom and push its consequences to completion. When a value is
assembled from $m$ ingredients by $m-1$ binary combinations, the order is recorded by a binary
tree, and we ask how the depth of the final value depends on the tree. The answer: entirely
through the tree's \textbf{height}, which is controllable within sharp universal bounds.

\paragraph{Contributions.}
(1) the foundational bound (Thm.~\ref{thm:fund});
(2) height--leaf duality (Thms.~\ref{thm:leafpow}--\ref{thm:cloglower});
(3) the optimality sandwich (Thms.~\ref{thm:balopt}--\ref{thm:catworst});
(4) the exponential reassociation gap (Thm.~\ref{thm:expgap});
(5) optimal height for all sizes (Thm.~\ref{thm:mkbal});
(6) scale covariance (Thms.~\ref{thm:scaled}--\ref{thm:least});
(7) the two-sided witness sandwich and universal overhead (Thms.~\ref{thm:wsand}--\ref{thm:univ});
(8) bridges to Hensel lifting, composition, and the tropical functor (Sec.~\ref{sec:bridges}).

\section{Definitions}

\begin{definition}[Depth carrier]
A \emph{depth carrier} is $X = (K, \oplus, \depth)$ with a type $K$, a binary combination
$\oplus : K \to K \to K$, and a depth measure $\depth : K \to \mathbb{N}$ satisfying the
\textbf{unit-cost ultrametric law}
\[ \forall x\,y,\quad \depth(x \oplus y) \le \max(\depth x, \depth y) + 1. \]
\end{definition}

\begin{definition}[Strict carrier]
A depth carrier is \emph{strict} (idempotent/zero-cost) if $\depth(x \oplus y) \le
\max(\depth x, \depth y)$ with no $+1$ slack.
\end{definition}

\begin{definition}[Unit-cost witness]
The \emph{witness carrier} is $(\mathbb{N}, \oplus, \mathrm{id})$ with $x \oplus y :=
\max(x,y) + 1$. The law holds with equality, so it is extremal.
\end{definition}

\begin{definition}[Combination tree]
$\mathrm{OpTree}\,K$ is the type of binary trees with $K$-valued leaves: $\mathrm{leaf}\,k$ or
$\mathrm{node}\,l\,r$. By structural recursion:
\begin{align*}
\eval_\oplus(\mathrm{leaf}\,k) &= k, & \eval_\oplus(\mathrm{node}\,l\,r) &= \eval_\oplus l \oplus \eval_\oplus r,\\
\height(\mathrm{leaf}\,\_) &= 0, & \height(\mathrm{node}\,l\,r) &= \max(\height l, \height r)+1,\\
\numLeaves(\mathrm{leaf}\,\_) &= 1, & \numLeaves(\mathrm{node}\,l\,r) &= \numLeaves l + \numLeaves r,\\
\maxLeafDepth(\mathrm{leaf}\,k) &= \depth k, & \maxLeafDepth(\mathrm{node}\,l\,r) &= \max(\maxLeafDepth l, \maxLeafDepth r).
\end{align*}
\end{definition}

\begin{definition}[Canonical extremal trees]
The \emph{balanced} tree $\mathrm{balanced}\,k\,n$ is $\mathrm{leaf}\,k$ for $n=0$ and
$\mathrm{node}(\mathrm{balanced}\,k\,n)(\mathrm{balanced}\,k\,n)$ for $n+1$; it has height $n$
and $2^n$ leaves. The \emph{caterpillar} $\mathrm{caterpillar}\,k\,n$ is $\mathrm{leaf}\,k$ for
$n=0$ and $\mathrm{node}(\mathrm{caterpillar}\,k\,n)(\mathrm{leaf}\,k)$ for $n+1$; it has
height $n$ and $n+1$ leaves.
\end{definition}

\begin{definition}[Cost-$c$ carrier]
A \emph{cost-$c$ carrier} is $(K, \oplus, \depth, c)$ with $\depth(x \oplus y) \le
\max(\depth x, \depth y) + c$. A depth carrier is the case $c=1$.
\end{definition}

\section{The Fundamental Combination-Tree Bound}

\begin{theorem}[Combination-tree depth bound]\label{thm:fund}
For any depth carrier $X$ and tree $t$,
\[ \depth(\eval t) \le \maxLeafDepth t + \height t. \]
\end{theorem}
\begin{proof}[Proof sketch]
Induction on $t$. The leaf case is an equality. For $\mathrm{node}\,l\,r$, the unit-cost law
gives $\depth(\eval l \oplus \eval r) \le \max(\depth(\eval l), \depth(\eval r)) + 1$;
combining with the inductive hypotheses and
$\max(a+p,b+q) \le \max(a,b)+\max(p,q)$ and $\height(\mathrm{node}\,l\,r)=\max(\height l,\height r)+1$
closes the goal by linear arithmetic.
\end{proof}

\begin{theorem}[Strict carriers have no overhead]\label{thm:strict}
If $X$ is strict, then $\depth(\eval t) \le \maxLeafDepth t$ for every tree.
\end{theorem}
\begin{proof}[Proof sketch]
The same induction without the $+1$, so the height term never accrues.
\end{proof}

\section{Height--Leaf Duality}

\begin{theorem}[Leaf count is at most $2^{\height}$]\label{thm:leafpow}
For every tree $t$, $\numLeaves t \le 2^{\height t}$.
\end{theorem}
\begin{proof}[Proof sketch]
Induction; for a node, $\numLeaves \le 2^{h_l}+2^{h_r} \le 2\cdot 2^{\max(h_l,h_r)} =
2^{\max(h_l,h_r)+1}$.
\end{proof}

\begin{theorem}[Height is below the leaf count]\label{thm:heightleaf}
For every tree $t$, $\height t + 1 \le \numLeaves t$.
\end{theorem}
\begin{proof}[Proof sketch]
Induction; for a node with $h_l \ge h_r$ (WLOG), $\height+1 = h_l+2 \le (\numLeaves l + 1)+1
\le \numLeaves l + \numLeaves r$.
\end{proof}

\begin{theorem}[Universal logarithmic lower bound]\label{thm:cloglower}
For every tree $t$, $\clog{\numLeaves t} \le \height t$.
\end{theorem}
\begin{proof}[Proof sketch]
Apply $\lceil \log_2 m\rceil \le h \iff m \le 2^h$ to Theorem~\ref{thm:leafpow}.
\end{proof}

Together these give, for every tree,
\[ \clog{\numLeaves t} \;\le\; \height t \;\le\; \numLeaves t - 1. \]

\section{The Optimality Sandwich}

\begin{theorem}[Balanced is optimal]\label{thm:balopt}
$\height(\mathrm{balanced}\,k\,n) = \clog{\numLeaves(\mathrm{balanced}\,k\,n)}$.
\end{theorem}
\begin{proof}[Proof sketch]
$\height = n$, $\numLeaves = 2^n$, $\lceil\log_2 2^n\rceil = n$.
\end{proof}

\begin{theorem}[Caterpillar is worst]\label{thm:catworst}
$\height(\mathrm{caterpillar}\,k\,n) = \numLeaves(\mathrm{caterpillar}\,k\,n) - 1$.
\end{theorem}
\begin{proof}[Proof sketch]
$\height = n$, $\numLeaves = n+1$.
\end{proof}

\begin{theorem}[Exponential reassociation gap]\label{thm:expgap}
For $n \ge 2$, under the unit-cost operation $\eval(\mathrm{balanced}\,0\,n) = n$ and
$\eval(\mathrm{caterpillar}\,0\,(2^n-1)) = 2^n - 1$, with both trees having $2^n$ leaves.
\end{theorem}
\begin{proof}[Proof sketch]
$\eval(\mathrm{balanced}\,0\,n) = n$ and $\eval(\mathrm{caterpillar}\,0\,m) = m$ under
$\max(\cdot,\cdot)+1$; leaf counts match, and $n < 2^n - 1$ for $n \ge 2$.
\end{proof}

\section{Optimal Height for Every Leaf Count}

\begin{theorem}[Optimal reassociation exists for every leaf count]\label{thm:mkbal}
For every $m \ge 1$ there is a tree $\mathrm{mkBalanced}\,k\,m$ with $\numLeaves = m$ and
$\height = \clog{m}$. Hence Theorem~\ref{thm:cloglower} is attained for all $m$.
\end{theorem}
\begin{proof}[Proof sketch]
Strong recursion: split $m = \lceil m/2\rceil + \lfloor m/2\rfloor$, recurse, combine. Use
$\lceil\log_2 m\rceil = \lceil\log_2\lceil m/2\rceil\rceil + 1$ for $m \ge 2$.
\end{proof}

\section{Scale Covariance: The Cost Constant}

\begin{theorem}[Scaled combination-tree bound]\label{thm:scaled}
For a cost-$c$ carrier and tree $t$, $\depth(\eval t) \le \maxLeafDepth t + c\cdot\height t$.
\end{theorem}
\begin{proof}[Proof sketch]
The induction of Theorem~\ref{thm:fund} with $+c$, using
$\max(a+cx, b+cy) \le \max(a,b) + c\max(x,y)$.
\end{proof}

\begin{theorem}[Least working constant]\label{thm:least}
A constant $c$ makes $\depth(x\oplus y) \le \max(\depth x,\depth y)+c$ hold for every depth
carrier iff $1 \le c$.
\end{theorem}
\begin{proof}[Proof sketch]
Sufficiency from the unit-cost law; necessity from the witness at $0 \oplus 0$, where
$\depth = 1 = \max(0,0)+1$.
\end{proof}

\section{Two-Sided Witness Bound and Universal Overhead}

\begin{theorem}[Witness sandwich]\label{thm:wsand}
On the witness carrier, $\maxLeafDepth t \le \eval t \le \maxLeafDepth t + \height t$, both
ends attained.
\end{theorem}
\begin{proof}[Proof sketch]
Upper: Theorem~\ref{thm:fund}. Lower: $\max(x,y)+1 \ge \max(x,y)$, so each node weakly
increases the running max; no leaf value is lost.
\end{proof}

\begin{theorem}[Universal linear overhead]\label{thm:univ}
For every depth carrier and tree, $\depth(\eval t) \le \maxLeafDepth t + (\numLeaves t - 1)$.
\end{theorem}
\begin{proof}[Proof sketch]
Combine Theorem~\ref{thm:fund} with $\height t \le \numLeaves t - 1$.
\end{proof}

\section{Bridges and Applications}\label{sec:bridges}

\subsection{Hensel lifting and Newton precision}

A \emph{composition-depth carrier} $(M, \circ, \vdepth)$ obeys $\vdepth(f \circ g) \le
\max(\vdepth f, \vdepth g)+1$ and is a depth carrier, so all tree results transfer. For the
doubling carrier $(\mathbb{N}, \max(\cdot,\cdot)+1, \mathrm{id})$, the $k$-fold doubling tree
$\mathrm{balanced}\,0\,k$ satisfies
\[ \vdepth(\eval) = \height = k, \qquad 2^{\vdepth(\eval)} = 2^k. \]
This recovers the exponential-precision Newton/Hensel certificate as the height of a balanced
composition tree.

\subsection{The tropical 1-Lipschitz functor}

Let the tropical semiring be $(\mathbb{N}, \max, +)$. The unit-cost law states that
$\depth$ is \textbf{1-Lipschitz} into tropical addition:
$\depth(x \oplus y) \le \max(\depth x, \depth y) + 1$. The combination-tree bound is the
functorial propagation of this property along trees, with overhead exactly the height.

\section{Algorithms}

\begin{algorithm}[Median-split optimal tree]
Given $m \ge 1$: if $m=1$ return a leaf; else split $m = \lceil m/2\rceil + \lfloor m/2\rfloor$,
recurse on each half, return their node. Time $\Theta(m)$, height $\clog{m}$.
\end{algorithm}

\begin{algorithm}[Height/leaf certificate]
Compute $\height$, $\numLeaves$; verify $\clog{\numLeaves} \le \height \le \numLeaves - 1$ in
$\Theta(\text{size})$.
\end{algorithm}

\section{Discussion}

The unit-cost law contributes one unit per node, and the only surviving tree statistic is the
height. The duality $\clog{m} \le \height \le m-1$ turns ``balanced is better'' into a sharp,
attained, exponential law. The bridges to Hensel lifting, composition, and tropical geometry
are literal instances of one axiom; the optimal strategy and exact cost are theorems about
the axiom, inherited by every model.

\section{Future Directions}

\begin{conjecture}[Tropical Kraft--Huffman optimum]
Fix a multiset $L$ of $m$ leaf values on the witness carrier. The minimum of $\eval t$ over
trees with leaf multiset $L$ equals $\maxLeafDepth L + \clog{m}$ when leaves are equal, and in
general is the least $D$ with $\sum_{\ell\in L} 2^{\depth(\ell)-D} \le 1$.
\end{conjecture}

\begin{conjecture}[Lax 2-functor upgrade]
Depth carriers with cost-non-increasing morphisms form a category, and $\depth$ extends to a
lax functor into $(\mathbb{N},\max,+1)$ for which the combination-tree bound is natural.
\end{conjecture}

\section{Conclusion}

Height is the only cost, and $\clog{\text{leaves}} \le \height \le \text{leaves}-1$ pins it on
both sides.

\end{document}

